function addToCart(code){let p=db.products.find(x=>x.code===code);if(!p)return;let line=cart.find(x=>x.code===code&&!x.dealName);if(line)line.qty++;else cart.push({code:p.code,name:p.name,qty:1,rate:p.rate,dealName:''});if(cartQtyFor(code)>available(p)) {cart[cart.length-1].qty--;if(cart[cart.length-1].qty<=0)cart.pop();return alert('Quantity exceeds available stock.')}updateCartCount();}
function cartQtyFor(code){return cart.filter(x=>x.code===code).reduce((a,x)=>a+x.qty,0)}
function addDealToCart(index){let d=(db.deals||[])[index];if(!d)return;for(let x of d.items){let p=db.products.find(p=>p.code===x.code);if(!p||cartQtyFor(x.code)+x.qty>available(p))return alert('Deal cannot be added: insufficient stock for '+(p?.name||x.code))}cart.push({dealName:d.name,items:clone(d.items),qty:1,rate:d.price,code:'DEAL-'+Date.now(),name:d.name});updateCartCount()}
function updateCartCount(){$('cartCount').textContent=cart.reduce((a,x)=>a+x.qty,0)}
