function printOnlineInvoice(id){let o=db.orders.find(x=>x.id===id);if(!o||!o.bill)return;let r={bill:o.bill,date:o.date,cashier:'ONLINE',customer:o.customer,customerType:'Online Store Customer',customerPhone:o.phone,saleChannel:'Online Store',rider:o.rider||'',riderBike:o.riderBike||'',riderPhone:o.riderPhone||'',riderDetails:o.riderDetails||'',currency:'PKR',payment:o.payment,paymentStatus:o.paymentReceived?'PAID / RECEIVED':'PENDING',bankSelected:o.bankSelected||'',bankAccountTitle:db.bankTitle||'',bankAccountNumber:db.bankNumber||'',bankIban:db.bankIban||'',received:o.paymentReceived?fx(o.total,o.currency,'PKR'):0,balance:o.paymentReceived?0:fx(o.total,o.currency,'PKR'),gst:fx(o.gst||0,o.currency,'PKR'),deliveryFee:fx(o.deliveryFee||0,o.currency,'PKR'),deliveryDiscount:fx(o.deliveryDiscount||0,o.currency,'PKR'),total:fx(o.total,o.currency,'PKR'),lines:o.items.map(i=>({code:i.code,name:i.name,qty:i.qty,rate:i.rate,discPct:0,net:i.qty*i.rate}))};printReceipt(r)}
function returnOnlineOrder(id){let o=db.orders.find(x=>x.id===id);if(!o||!o.converted)return alert('Only confirmed orders can be returned.');let max=o.items.reduce((a,i)=>a+i.qty,0)-(o.returnedQty||0),q=Number(prompt(`Return quantity (1-${max})`,String(max)));if(!Number.isInteger(q)||q<1||q>max)return;let remaining=q,returnValue=0;for(let i of o.items){let n=Math.min(remaining,i.qty);if(n){let row=db.sales.find(s=>s.orderId===o.id&&s.code===i.code);if(row){let can=row.qty-(row.returnQty||0),take=Math.min(can,n);row.returnQty=(row.returnQty||0)+take;let unitReturn=row.rate*(1-(+row.discPct||0)/100)+((+row.gst||0)/(row.qty||1));row.returnAmount=(row.returnAmount||0)+take*unitReturn;returnValue+=take*unitReturn;remaining-=take;}}}o.returnedQty=(o.returnedQty||0)+q;let refunded=confirm(`Return value ${rawMoney(fx(returnValue,'PKR',o.currency),o.currency)}. OK = refund already paid to customer; Cancel = refund pending.`);o.refundStatus=refunded?'Refunded':'Refund Pending';o.refundedAmount=(o.refundedAmount||0)+(refunded?fx(returnValue,'PKR',o.currency):0);if(refunded){db.refunds??=[];db.refunds.push({date:new Date().toISOString().slice(0,10),bill:o.bill,orderId:o.id,amount:returnValue,currency:'PKR',method:o.payment,type:'Online return'})}if(o.returnedQty>=o.items.reduce((a,i)=>a+i.qty,0))o.status='Returned';save();notifyUser('Online return recorded',`${q} item(s) returned from ${id} — ${o.refundStatus}`);render()}
function renderReports(){let c=$('reportCurrency').value||'PKR',cash=db.sales.filter(s=>!s.voided&&(s.payment==='Cash'||s.payment==='Cash on Delivery')).reduce((a,s)=>a+fx((+s.net||0)-(+s.returnAmount||0),s.currency||'PKR',c),0),card=db.sales.filter(s=>!s.voided&&!(s.payment==='Cash'||s.payment==='Cash on Delivery')).reduce((a,s)=>a+fx((+s.net||0)-(+s.returnAmount||0),s.currency||'PKR',c),0),disc=db.sales.filter(s=>!s.voided).reduce((a,s)=>a+fx(s.discount,s.currency||'PKR',c),0),ret=db.sales.filter(s=>!s.voided).reduce((a,s)=>a+fx(s.returnAmount||0,s.currency||'PKR',c),0);$('cashReport').textContent=rawMoney(cash,c);$('cardReport').textContent=rawMoney(card,c);$('discountReport').textContent=rawMoney(disc,c);$('returnsReport').textContent=rawMoney(ret,c);let refunds=(db.refunds||[]).reduce((a,r)=>a+fx(+r.amount||0,r.currency||'PKR',c),0);$('refundsReport').textContent=rawMoney(refunds,c);let groups={};db.sales.filter(s=>!s.voided).forEach(s=>{let m=s.date.slice(0,7);groups[m]??={n:0,total:0,cash:0,other:0};groups[m].n++;groups[m].total+=fx((+s.net||0)-(+s.returnAmount||0),s.currency||'PKR',c);groups[m][(s.payment==='Cash'||s.payment==='Cash on Delivery')?'cash':'other']+=fx((+s.net||0)-(+s.returnAmount||0),s.currency||'PKR',c)});$('monthRows').innerHTML=Object.keys(groups).sort().reverse().map(m=>`<tr><td>${m}</td><td>${groups[m].n}</td><td>${rawMoney(groups[m].total,c)}</td><td>${rawMoney(groups[m].cash,c)}</td><td>${rawMoney(groups[m].other,c)}</td></tr>`).join('')}
