function refreshRiderSelectors(){let opts='<option value="">Select rider (optional)</option>'+(db.riders||[]).map(r=>`<option value="${esc(r.id)}">${esc(r.name)} · ${esc(r.bike)}</option>`).join('');if($('posRider')){$('posRider').innerHTML=opts;}document.querySelectorAll('.orderRider').forEach(sel=>{let o=db.orders.find(x=>x.id===sel.dataset.id);sel.innerHTML=opts;sel.value=o?.riderId||''})}
function riderById(id){return (db.riders||[]).find(r=>r.id===id)}
function saveSettings(){db.businessName=$('businessName').value.trim()||'Accounts Management';db.currency=$('baseCurrency').value;db.threshold=+$('threshold').value||0;db.whatsapp=$('whatsapp').value.trim();db.bankName=$('bankName').value.trim();db.bankTitle=$('bankTitle').value.trim();db.bankNumber=$('bankNumber').value.trim();db.bankIban=$('bankIban').value.trim();db.bankNames=$('bankNames').value.split(',').map(x=>x.trim()).filter(Boolean);db.usdPaymentOption=$('usdPaymentOption').value;db.usdPaymentDetails=$('usdPaymentDetails').value.trim();db.storeEta=$('storeEta').value==='custom'?'custom':+$('storeEta').value;db.deliveryFee=+$('deliveryFee').value||0;db.deliveryDiscount=+$('deliveryDiscount').value||0;db.defaultGst=+$('defaultGst').value||0;db.storeDisplayName=$('storeDisplayName').value.trim()||'Avenuex.Online-Store';db.receiptWidth=+$('receiptWidth').value||80;db.supportPhones=Array.from({length:4},(_,i)=>$('supportPhone'+(i+1)).value.trim());db.supportEmails=Array.from({length:4},(_,i)=>$('supportEmail'+(i+1)).value.trim());Object.keys(currencies).filter(c=>c!=='PKR').forEach(c=>{let v=+$('rate_'+c).value;if(v>0)db.rates[c]=v});save();fillCurrencies();renderSettingsExtras();render();alert('Settings saved on this device.')}
function importCsv(e){let f=e.target.files[0];if(!f)return;let reader=new FileReader();reader.onload=()=>{let rows=parseCSV(reader.result),h=rows.shift().map(x=>x.toLowerCase().replace(/[^a-z]/g,'')),ix=(...a)=>h.findIndex(x=>a.includes(x)),ci=ix('itemcode','code','sku'),ni=ix('itemname','name','product'),bi=ix('brand'),oi=ix('openingqty','opening'),pi=ix('purchaserate','purchase'),si=ix('stockinqty','stockin'),ri=ix('salerate','rate');if(ci<0||ni<0)return alert('CSV requires Item Code and Item Name headers.');rows.forEach(r=>{let p={code:r[ci],name:r[ni],brand:r[bi]||'',unit:'pcs',opening:+r[oi]||0,purchase:+r[pi]||0,stockIn:+r[si]||0,rate:+r[ri]||0},old=db.products.find(x=>x.code===p.code);if(old)Object.assign(old,p);else db.products.push(p)});save();render();alert('CSV import complete.')};reader.readAsText(f);e.target.value=''}
function parseCSV(t){let a=[],r=[],v='',q=false;for(let i=0;i<t.length;i++){let c=t[i];if(c==='"'&&q&&t[i+1]==='"'){v+='"';i++}else if(c==='"')q=!q;else if(c===','&&!q){r.push(v);v=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&t[i+1]==='\n')i++;r.push(v);if(r.some(x=>x.trim()))a.push(r);r=[];v=''}else v+=c}r.push(v);if(r.some(x=>x.trim()))a.push(r);return a}
function exportSales(){let header=['Date','Bill No','Item Code','Item Name','Qty','Rate','Gross','Discount','Net','Currency','Payment'];let lines=db.sales.map(s=>[s.date,s.bill,s.code,s.name,s.qty,s.rate,s.gross,s.discount,s.net,s.currency,s.payment]);download([header,...lines].map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\n'),'item-sales.csv','text/csv')}
function download(data,name,type){let a=document.createElement('a'),u=URL.createObjectURL(new Blob([data],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

let pendingDealImage='';
function addDealItemToBuilder(){let code=$('dealCodeSelect').value,qty=+$('dealItemQty').value||1;if(!code||qty<1)return;let existing=$('dealItems').value.trim();$('dealItems').value=(existing?existing+',':'')+code+':'+qty}
function readDealImage(e){let f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/'))return alert('Choose an image file.');if(f.size>1500000)return alert('Image must be 1.5 MB or smaller.');let r=new FileReader();r.onload=()=>{pendingDealImage=r.result;$('dealImagePreview').src=pendingDealImage};r.readAsDataURL(f)}
function deleteAllDeals(){if(!(db.deals||[]).length)return;if(!confirm('Delete all saved deals? Product stock and sales history will remain.'))return;db.deals=[];save();renderStore()}
function deleteSelectedProducts(){let codes=[...document.querySelectorAll('.productSelect:checked')].map(x=>x.value);if(!codes.length)return alert('Select products first.');if(!confirm(`Delete ${codes.length} selected products from Stock Master? Historical sales will remain.`))return;db.products=db.products.filter(p=>!codes.includes(p.code));save();render()}
function deleteAllProducts(){if(!db.products.length)return;if(!confirm('Delete ALL Stock Master products? Historical sales and orders remain. Export backup first.'))return;db.products=[];save();render()}
function deleteSelectedSales(){let keys=[...document.querySelectorAll('.saleSelect:checked')].map(x=>x.value);if(!keys.length)return alert('Select sales rows first.');if(!confirm(`Permanently delete ${keys.length} selected sale lines?`))return;db.sales=db.sales.filter(s=>!keys.includes(s.bill+'|'+s.code));save();render()}
function deleteAllSales(){if(!db.sales.length)return;if(!confirm('Permanently delete ALL sales history? Export backup first.'))return;db.sales=[];save();render()}
function recordWaste(){let code=$('wasteCode').value.trim(),qty=+$('wasteQty').value||0,reason=$('wasteReason').value.trim(),p=db.products.find(x=>x.code===code);if(!p||qty<1)return alert('Choose a valid stock code and quantity.');if(qty>available(p))return alert('Wastage quantity exceeds available stock.');db.wastage??=[];db.wastage.push({id:'WST-'+Date.now(),code,name:p.name,qty,reason,date:new Date().toISOString().slice(0,10)});save();$('wasteQty').value=1;$('wasteReason').value='';render();alert('Wastage recorded and stock reduced.')}
function submitStoreSupportMessage(){let m={id:'MSG-'+Date.now(),customer:$('storeSupportName').value.trim()||'Customer',phone:$('storeSupportPhone').value.trim(),type:$('storeSupportType').value,message:$('storeSupportMessage').value.trim(),date:new Date().toISOString(),reply:'',status:'Open'};if(!m.message)return alert('Write your message first.');db.supportMessages??=[];db.supportMessages.push(m);save();$('storeSupportMessage').value='';renderSupportInbox();alert('Your message has been saved to the merchant support inbox.')}
function submitSupportMessage(){let m={id:'MSG-'+Date.now(),customer:$('supportCustomer').value.trim()||'Customer',phone:$('supportCustomerPhone').value.trim(),type:$('supportType').value,message:$('supportMessage').value.trim(),date:new Date().toISOString(),reply:'',status:'Open'};if(!m.message)return alert('Enter customer message.');db.supportMessages??=[];db.supportMessages.push(m);save();$('supportMessage').value='';renderSupportInbox();alert('Message added to local merchant inbox.')}
function renderSupportInbox(){let a=db.supportMessages||[];$('supportInbox').innerHTML=a.slice().reverse().map(m=>`<div class="recent"><span><b>${esc(m.customer)} · ${esc(m.type)}</b><small>${esc(m.phone)} · ${esc(m.message)}<br>Status: ${esc(m.status)}${m.reply?'<br>Reply: '+esc(m.reply):''}</small></span><button class="link" data-replymsg="${m.id}">Reply</button></div>`).join('')||'No support messages yet.';document.querySelectorAll('[data-replymsg]').forEach(b=>b.onclick=()=>{let m=a.find(x=>x.id===b.dataset.replymsg),r=prompt('Write reply to customer:');if(r===null)return;m.reply=r;m.status='Replied';save();renderSupportInbox()})}
function getCustomerLocation(){if(!navigator.geolocation)return alert('Location is not available in this browser.');$('locationStatus').textContent='Requesting location permission…';navigator.geolocation.getCurrentPosition(pos=>{let v=`GPS: ${pos.coords.latitude.toFixed(6)}, ${pos.coords.longitude.toFixed(6)}`;$('oAddress').value=($('oAddress').value+' '+v).trim();$('locationStatus').textContent='Current location added. Add house / street details if needed.'},err=>{$('locationStatus').textContent='Location permission denied or unavailable. Type address manually.'},{enableHighAccuracy:true,timeout:12000})}
function renderSettingsExtras(){ $('receiptWidth').value=String(db.receiptWidth||58);$('riderList').innerHTML=(db.riders||[]).map(r=>`<div class="rider-card"><div><b>${esc(r.name)} · ${esc(r.bike)}</b><small>${esc(r.phone)}${r.details?' · '+esc(r.details):''}</small></div><button type="button" class="link" onclick="removeRider('${r.id}')">Remove</button></div>`).join('')||'<p class="hint">No rider profiles added yet.</p>';refreshRiderSelectors();$('storeEta').value=String(db.storeEta??45);$('deliveryFee').value=db.deliveryFee??0;$('deliveryDiscount').value=db.deliveryDiscount??50;$('defaultGst').value=db.defaultGst??0;$('storeDisplayName').value=db.storeDisplayName||'Avenuex.Online-Store';$('usdPaymentOption').value=db.usdPaymentOption||'USD Bank Transfer';$('usdPaymentDetails').value=db.usdPaymentDetails||'';$('oEtaDisplay').value=db.storeEta==='custom'?'Delivery time confirmed by merchant':`${db.storeEta||45} minutes`;$('oEta').value=db.storeEta||45;renderSupportInbox();$('wasteRows').innerHTML=(db.wastage||[]).slice().reverse().map(w=>`${esc(w.date)} · ${esc(w.name)} (${esc(w.code)}) × ${w.qty} — ${esc(w.reason)}`).join('<br>')||'No wastage recorded.'}

window.removeRider=removeRider;init();